import React , { useEffect, useState }from 'react';
import { useNavigate } from 'react-router-dom';
import './ASidebar.css';
import { baseURL } from '../../api';

const ASidebar = ({onLogout, onNavigate , user}) => {
    const [firstName, setFirstName] = useState('');
    const navigate = useNavigate();

    useEffect(() => {
        const fetchProfile = async () => {
            try {
                const res = await fetch(baseURL+'/profile', {
                credentials: 'include',
                });

                if (res.ok) {
                const data = await res.json();
                setFirstName(data.firstName || 'User');
                } else {
                console.error('Failed to load profile', data.message);
                }
            } catch (err) {
                console.error('Error fetching profile:', err);}
        };
        fetchProfile();
    }, []);

    const handleLogout = async () => {
        try {
        const res = await fetch(baseURL+'/logout', {
            method: 'POST',
            credentials: 'include',
        });

        if (res.ok) {
            alert(data.message);
            navigate('/login');
            // window.location.href = '/login'; // Redirect to home or login page
        } else {
            alert('Logout failed');
        }
        } catch (err) {
        console.error('Logout error:', err);
        alert('Server error');
        }
    };
    return (
        <div className="admin-sidebar">
        <div className="admin-profile-sidebar">
            {/* <img src="data:image/png;base64," alt="Profile" /> */}
             <img src={baseURL+`/uploads/${user?.profilePic}`} alt="" />
            <p>{firstName}</p>
        </div>
        <ul className="admin-nav-links-sidebar">
            <li onClick={() => navigate('/portal/admin')}>Dashboard</li>
            <li onClick={() => navigate('/admin/users')}>Users</li>
            <li onClick={() => navigate('/admin/publications')}>Publications</li>
            <li onClick={()=> navigate('/admin/todaysignup')}>Signups</li>
            <li onClick={onLogout} style={{ cursor: 'pointer', color: 'white' }}>Log out</li>
        </ul>
        </div>
    );
};

export default ASidebar;