import React , { useEffect, useState }from 'react';
import './Sidebar.css';
import { baseURL } from '../api';

const Sidebar = ({onLogout, onNavigate ,user }) => {
    const [firstName, setFirstName] = useState('');

    useEffect(() => {
        const fetchProfile = async () => {
            try {
                const res = await fetch(baseURL+'/profile', {
                credentials: 'include',
                });

                if (res.ok) {
                const data = await res.json();
                setFirstName(data.firstName || 'User');
                } else {
                console.error('Failed to load profile', data.message);
                }
            } catch (err) {
                console.error('Error fetching profile:', err);}
        };
        fetchProfile();
    }, []);

    const handleLogout = async () => {
        try {
        const res = await fetch(baseURL+'/logout', {
            method: 'POST',
            credentials: 'include',
        });

        if (res.ok) {
            alert(data.message);
            window.location.href = '/login'; // Redirect to home or login page
        } else {
            alert('Logout failed');
        }
        } catch (err) {
        console.error('Logout error:', err);
        alert('Server error');
        }
    };
    return (
        <div className="sidebar">
        <div className="profile-sidebar">
            <img src={baseURL+`/uploads/${user?.profilePic}`} alt="" />
            {/* <img src="data:image/png;base64," alt="Profile" /> */}
            <p>{firstName}</p>
        </div>
        <ul className="nav-links-sidebar">
            <li onClick={() => onNavigate('dashboard')}>Dashboard</li>
            <li onClick={() => onNavigate('myresearch')}>My Research</li>
            <li onClick={() => onNavigate('settings')}>Settings</li>
            <li onClick={onLogout} style={{ cursor: 'pointer', color: 'white' }}>
            Log out
            </li>
        </ul>
        </div>
    );
};

export default Sidebar;